91: __global__ void gemm_impl0(const uint32_t m, const uint32_t n, const uint32_t k,
92:                            fp16 const *__restrict__ a,
93:                            fp16 const *__restrict__ b,
94:                            fp32 const *c,
95:                            fp32 *d, const uint32_t lda, const uint32_t ldb,
96:                            const uint32_t ldc, const uint32_t ldd,
97:                            const fp32 alpha, const fp32 beta) {
98:   // Create frags
99:   auto fragA = wmma::fragment<wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K, fp16,
100:                               wmma::row_major>();
101:   auto fragB = wmma::fragment<wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K, fp16,
102:                               wmma::col_major>();
103:   auto fragC = wmma::fragment<wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, fp32>();
104:   auto fragAcc = wmma::fragment<wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, fp32>();
105: 
106:   wmma::fill_fragment(fragAcc, 0.0f);
107: 
108:   auto cRow = blockIdx.x * WMMA_M;
109:   auto cCol = blockIdx.y * WMMA_N;
110: 
111:   // Load the inputs
112:   for (int n = 0; n < k; n += WMMA_K) {
113:     // Because the mapping of elements to threads in a warp is opaque,
114:     // each thread just passes the address of the first element
115:     wmma::load_matrix_sync(fragA, a + cRow * lda + n, lda);
116:     wmma::load_matrix_sync(fragB, b + cCol * ldb + n, ldb);
117: 
118:     // Matrix multiply - accumulate using MFMA units
119:     wmma::mma_sync(fragAcc, fragA, fragB, fragAcc);
120: 
121:     // Fetch C matrix
122:     wmma::load_matrix_sync(fragC, c + cRow * ldc + cCol, ldc, wmma::mem_row_major);
123: 
124:     // D = alpha * A x B + beta * C
125:     for (int i = 0; i < fragC.num_elements; ++i) {
126:       fragC.x[i] = alpha * fragAcc.x[i] + beta * fragC.x[i];
127:     }
128:   }
129: 
130:   // Store to D (by a single wave)
131:   wmma::store_matrix_sync(d + cRow * ldd + cCol, fragC, ldd, wmma::mem_row_major);
132: }

